                                        "links": [
                                          "local_5f255159617746bd9e46f86e07d2d037",
                                          "f_227_4068"
                                        ],
                                        "notes": "Название экрана:\nЗадания технолога — общий экран; варианты заданий не создают отдельные экраны.\n\nСостав экрана:\n• Список заданий и карточка: Позиции, база, цвет, масса, рецепт, источник, переработка и выбранный способ колеровки.\n• Фильтры / сортировка: Тип задания, база, цвет, статус, срок.\n• Исполнитель, статус, срок, план/факт, причина проблемы и история.\n\nТекущее задание:\nРешить, использовать ли переработку для неколерованной продукции\nРоль: Технолог; для переработки сохраняется установленный приоритет ответственных.\nМесто: указано в задании; неподтверждённые места требуют уточнения.\n\nВход — как здесь оказаться:\n• Из списка заданий своего рабочего места.\n• Из обеспечения счёта — открыть связанное задание позиции.\n• Задание возникает по текущему маршруту после завершения предшествующего шага; сохранить счёт/позицию/партию и исходное задание.\n\nКнопки:\n• «Взять в работу» — закрепить исполнителя.\n• «Используем» — сохранить решение и продолжить существующую ветку.\n• «Нет/прошло 30 минут» — сохранить решение и продолжить существующую ветку.\n• «Проблема» — указать причину в карточке; сохранить факт и приостановить задание.\n\nРезультат:\nФакт / решение и проблема видны в исходной позиции на экране обеспечения счёта и в задании. После решения проблемы возобновляется то же задание с сохранённым фактом; повторный экземпляр не создаётся. Нет оборудования / проблема рецептуры — планировщик; сырьё — Снабжение; ошибка обмена — Оператор 1С только для устранения ошибки.\n\nСогласование:\nНовые экраны, кнопки и неподтверждённые роли / места требуют утверждения.\n\nПравила процесса:\nПравила исходного задания: Задание технологу — использовать переработку или нет? Для неколерованной продукции при большом объёме. Весь доступный список переработки: 1. Совпадает база и цвет. 2. Совпадает только цвет. 3. Все остальные позиции. Фильтр по базе; остальные позиции доступны для ручного выбора. Использовать: подтвердить совместимость, партии и массу; новый замес — на оставшийся объём, выбранная переработка — в этот замес. Не использовать / 30 минут без решения: новый замес на весь объём.\nРешение по переработке: уведомление всем ответственным; приоритет главный технолог → технолог → планировщик. Общие 30 минут; более высокая роль может изменить решение в этом же окне. Источник: комментарий Данилы AAACArc6Lfc.",
