                                "notes": "Сформировать этикетки и стикеры автоматически по данным позиции: продукция, фасовка, количество, партия и требования к маркировке, включая кольцо и дополнительный текст при необходимости. Сохранить макет и документ печати в задании маркировки. Ручное задание офиса и прикрепление файла не требуются. ",
