                                                                "notes": "Название экрана:\nМаркировка — общий экран наклейки и переклейки.\n\nСостав экрана:\n• Задания: счёт/позиция, продукция, количество, фасовка, партия, место выполнения, макет и статус.\n• Карточка: этикетки и стикеры, документ печати, план/факт и причина проблемы.\n\nТекущее задание:\nНаклеить этикетки и стикеры на образцы после фасовки.\n\n\nВход — как здесь оказаться:\n• Из списка заданий маркировки или из обеспечения позиции счёта.\n• Задание создаётся по маршруту; макет и документ печати формируются автоматически по данным позиции.\n• После фасовки / перефасовки либо при переклейке уже готовой ГП. Для маркировки ёмкости переработки — после регистрации материала.\n\nКнопки:\n• «Взять в работу» — закрепить исполнителя после готовности продукции.\n• «Напечатать стикеры» — печать сформированного документа по актуальному макету.\n• «Выполнено» — подтвердить фактическое количество маркированной продукции и продолжить цепочку.\n• «Проблема» — указать причину; сохранить факт и показать проблему в исходной позиции/задании.\n\nРезультат:\nМаркировка подтверждена. Печать сама по себе не подтверждает наклейку. Требования к макету учитываются автоматически; ручное прикрепление файла не требуется.\n\nСогласование:\nПодготовка макета автоматическая по решению пользователя. Детали экрана требуют утверждения.",
