                                "notes": "Название экрана:\nЗадания склада — единый экран для всех складов.\n\nСостав экрана:\n• Фильтр по складу: ПФ, ГП, сырьё, переработка; можно выбрать несколько складов.\n• Сортировка: по складу, статусу, сроку и приоритету задания.\n• Список заданий: склад, счёт, позиция, действие, статус и исполнитель.\n• Карточка задания: ПФ, партия, план/факт кг, фасовка, тара, этикетки и стикеры.\n• План/факт, причина проблемы и история действий.\n\nТекущее задание:\nРасфасовать продукцию из ПФ; подтвердить массу, тару и партию.\nРоль: Сотрудник склада ПФ.\nМесто выполнения: Склад ПФ; место фасовки конкретного типа уточнить.\n\nВход — как здесь оказаться:\n• Источник задания: После подготовки стикеров выдано задание расфасовать продукцию.\n• Сотрудник открывает общий экран заданий склада, выбирает нужный склад и задание.\n• Из обеспечения счёта — «Открыть задание» по исходной позиции.\n\nКнопки:\n• «Взять в работу» — назначить себя исполнителем и начать это задание.\n• «Выполнено» — сохранить фактическое количество и продолжить цепочку; при недостаче не отмечать полное выполнение.\n• «Проблема» — указать причину в этой карточке, сохранить факт и приостановить задание.\n\nРезультат:\nВыполнение или проблема отображается в исходной позиции на экране обеспечения счёта. После решения продолжается то же задание с сохранённым фактом.\n\nСогласование:\nЭкран, входы и кнопки — предложение; требуют утверждения.",
