                                                            "links": [
                                                              "f_273_5214"
                                                            ],
                                                            "notes": "Название экрана:\nПлан замеса и оборудования — общий экран; варианты заданий не создают отдельные экраны.\n\nСостав экрана:\n• Список заданий и карточка: Потребности позиций, ПФ, пополнение, переработка, совместимые замесы, ёмкости, оборудование и очередь.\n• Фильтры / сортировка: База, статус замеса, оборудование, срок и срочность.\n• Исполнитель, статус, срок, план/факт, причина проблемы и история.\n\nТекущее задание:\nПодобрать допустимые пары «ёмкость + оборудование»\nРоль: Сотрудник по планированию производства.\nМесто: указано в задании; неподтверждённые места требуют уточнения.\n\nВход — как здесь оказаться:\n• Из списка заданий своего рабочего места.\n• Из обеспечения счёта — открыть связанное задание позиции.\n• Задание возникает по текущему маршруту после завершения предшествующего шага; сохранить счёт/позицию/партию и исходное задание.\n\nКнопки:\n• «Взять в работу» — закрепить исполнителя и начать задание.\n• «Подтвердить план» — сохранить факт / решение и продолжить маршрут по существующим связям.\n• «Проблема» — указать причину в карточке; сохранить факт и приостановить задание.\n\nРезультат:\nФакт / решение и проблема видны в исходной позиции на экране обеспечения счёта и в задании. После решения проблемы возобновляется то же задание с сохранённым фактом; повторный экземпляр не создаётся. Нет оборудования / проблема рецептуры — планировщик; сырьё — Снабжение; ошибка обмена — Оператор 1С только для устранения ошибки.\n\nСогласование:\nНовые экраны, кнопки и неподтверждённые роли / места требуют утверждения.\n\nПравила процесса:\nРазделение объёма выполняется в ветке «Нет» следующей проверки. После разделения подбор повторяется для каждой части; занятое оборудование учитывается при выборе времени, а не автоматически исключается как неподходящее.\nПри подборе учитывать продукт, плотность, рабочий объём и допустимую загрузку; неисправные пары исключить.",
