                                                                    "notes": "Сформировать этикетки и стикеры автоматически по данным позиции: продукция, фасовка, количество, партия и требования к маркировке, включая кольцо и дополнительный текст при необходимости. Сохранить макет и документ печати в задании маркировки. Ручное задание офиса и прикрепление файла не требуются. Стикеры: число товарных ёмкостей + 1 на арбитражный образец; этикетки — по товарной таре.",
                                                                    "review_status": "pending",
