                                                                "links": [
                                                                  "local_colored_a_to_pf"
                                                                ],
                                                                "notes": "Для собственных стандартных цветов Данила подтвердил выпуск ПФ с номером цвета. Продукция — колерованный компонент А; фактические материалы и склад-получатель нужно согласовать с 1С. Для нестандартного клиентского цвета порядок выпуска также требует уточнения. После колеровки компонент А передают на склад ПФ для фасовки и комплектации.",
